mapper.sql:
from sys_user u


        and (u.login_id ilike #{q.keywordLike} escape '\' or u.user_nm ilike #{q.keywordLike} escape '\')


        and exists (select 1 from sys_user_auth ua where ua.user_id = u.user_id and ua.auth_grp_cd = #{q.authGrpCd})

    and u.use_yn = #{q.useYn}
    and u.dept_id = #{q.deptId}
    and u.user_type = #{q.userType}
    and u.lock_yn = 'Y' and u.locked_until is null
    and u.lock_yn = 'Y' and u.locked_until > now()
    and not (u.lock_yn = 'Y' and (u.locked_until is null or u.locked_until > now()))

mapper.update:
update sys_user
   set user_nm = #{f.userNm}, email = #{f.email}, locale_cd = #{f.localeCd}, use_yn = #{f.useYn},
       dept_id = #{f.deptId},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where user_id = #{userId} and row_ver = #{f.rowVer}

update sys_user
   set session_not_before = now(), row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where user_id = #{userId} and row_ver = #{rowVer}

update sys_user
   set lock_yn = 'Y', locked_until = null,
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where user_id = #{userId} and row_ver = #{rowVer}

update sys_user
   set lock_yn = 'N', locked_until = null, login_fail_cnt = 0,
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where user_id = #{userId} and row_ver = #{rowVer}

update sys_auth_group
   set auth_grp_nm = #{f.authGrpNm}, sort_no = #{f.sortNo}, home_prog_cd = #{f.homeProgCd},
       admin_yn = #{f.adminYn}, use_yn = #{f.useYn},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where auth_grp_cd = #{f.authGrpCd} and row_ver = #{f.rowVer}

mapper.select:
select 
  from sys_menu m left join sys_prog p on p.prog_cd = m.prog_cd
 where m.menu_id = #{menuId}

mapper.update:
update sys_menu
   set parent_id = #{f.parentId}, menu_nm = #{f.menuNm}, prog_cd = #{f.progCd}, sort_no = #{f.sortNo},
       use_yn = #{f.useYn}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where menu_id = #{menuId} and row_ver = #{f.rowVer}
